338				// Increase the reserved numbers of all reservable items which the customer reserved. 
339	 			RMHashMap reservations = customer.getReservations();
340				for (String reservedKey : reservations.keySet())
341				{        
342					ReservedItem reserveditem = customer.getReservedItem(reservedKey);
343					Trace.info("RM::deleteCustomer(" + customerID + ") has reserved " + reserveditem.getKey() + " " +  reserveditem.getCount() +  " times");
344					ReservableItem item  = (ReservableItem)readData(reserveditem.getKey());
345					Trace.info("RM::deleteCustomer(" + customerID + ") has reserved " + reserveditem.getKey() + " which is reserved " +  item.getReserved() +  " times and is still available " + item.getCount() + " times");
346					item.setReserved(item.getReserved() - reserveditem.getCount());
347					item.setCount(item.getCount() + reserveditem.getCount());
348					writeData(item.getKey(), item);
349				}
350	
