405		public static Vector<String> parse(String command)
406		{
407			Vector<String> arguments = new Vector<String>();
408			StringTokenizer tokenizer = new StringTokenizer(command,",");
409			String argument = "";
410			while (tokenizer.hasMoreTokens())
411			{
412				argument = tokenizer.nextToken();
413				argument = argument.trim();
414				arguments.add(argument);
415			}
416			return arguments;
417		}
418	
