package Server.RMI;

import java.rmi.Remote;
import java.rmi.RemoteException;
import java.rmi.registry.LocateRegistry;
import java.rmi.registry.Registry;
import java.rmi.server.UnicastRemoteObject;

/** Stage 3: common RMI lifecycle for inventory and middleware endpoints. */
public final class RMIServer implements AutoCloseable {
    private final Remote service;
    private final Registry registry;
    private final String binding;
    private final boolean ownsRegistry;

    private RMIServer(Remote service, Registry registry, String binding, boolean ownsRegistry) {
        this.service = service;
        this.registry = registry;
        this.binding = binding;
        this.ownsRegistry = ownsRegistry;
    }

    public static RMIServer bind(Remote service, String name, int registryPort, String prefix, int objectPort)
            throws RemoteException {
        if (registryPort < 1 || registryPort > 65535 || objectPort < 0 || objectPort > 65535)
            throw new IllegalArgumentException("Invalid RMI port");
        Registry registry;
        boolean owned;
        try {
            registry = LocateRegistry.createRegistry(registryPort);
            owned = true;
        } catch (RemoteException busy) {
            registry = LocateRegistry.getRegistry(registryPort);
            registry.list();
            owned = false;
        }
        try {
            Remote stub = UnicastRemoteObject.exportObject(service, objectPort);
            registry.rebind(prefix + name, stub);
            return new RMIServer(service, registry, prefix + name, owned);
        } catch (RemoteException failure) {
            try { UnicastRemoteObject.unexportObject(service, true); } catch (Exception ignored) { }
            if (owned) try { UnicastRemoteObject.unexportObject(registry, true); } catch (Exception ignored) { }
            throw failure;
        }
    }

    public void installShutdownHook() {
        Runtime.getRuntime().addShutdownHook(new Thread(this::close, "rmi-shutdown-" + binding));
    }

    public void close() {
        try { registry.unbind(binding); } catch (Exception ignored) { }
        try { UnicastRemoteObject.unexportObject(service, true); } catch (Exception ignored) { }
        if (ownsRegistry) try { UnicastRemoteObject.unexportObject(registry, true); } catch (Exception ignored) { }
    }
}

package Server.RMI;

import Server.Common.Middleware;
import Server.Interface.IInventoryManager;
import java.rmi.registry.LocateRegistry;

/** Stage 3: RMI-specific startup only; customer and reservation logic lives in Common. */
public final class RMIMiddleware extends Middleware {
    public RMIMiddleware(String name, IInventoryManager flights, IInventoryManager cars, IInventoryManager rooms) {
        super(name, flights, cars, rooms);
    }

    private static IInventoryManager lookup(String endpoint, String name, String prefix) throws Exception {
        String[] parts = endpoint.split(":", -1);
        if (parts.length > 2 || parts[0].isEmpty())
            throw new IllegalArgumentException("Expected backend hostname[:registry-port]");
        int port = parts.length == 2 ? Integer.parseInt(parts[1]) : 1099;
        return (IInventoryManager) LocateRegistry.getRegistry(parts[0], port).lookup(prefix + name);
    }

    public static RMIMiddleware connect(String name, String flights, String cars, String rooms, String prefix)
            throws Exception {
        return new RMIMiddleware(name, lookup(flights, "Flights", prefix), lookup(cars, "Cars", prefix),
                lookup(rooms, "Rooms", prefix));
    }

    public static void main(String[] args) {
        if (args.length < 3 || args.length > 6) {
            System.err.println("Usage: RMIMiddleware Flights-host[:port] Cars-host[:port] Rooms-host[:port] [registry-port [prefix [object-port]]]");
            System.exit(1);
        }
