91	    private boolean acquire(int id, List<Booking> trip) throws RemoteException {
92	        Account account = accounts.get(id);
93	        if (account == null) return false;
94	        synchronized (account) {
95	            if (!account.exists) return false;
96	            if (account.deleting) throw new RemoteException("Customer deletion incomplete; retry deleteCustomer");
97	            releasePending(account);
98	            List<Booking> attempted = new ArrayList<>();
99	            boolean available = true;
100	            try {
101	                for (Booking booking : trip) {
102	                    attempted.add(booking);
103	                    booking.receipt = booking.manager.reserveInventory(booking.key, booking.quantity, booking.id);
104	                    if (booking.receipt == null) { available = false; break; }
105	                }
106	            } catch (RemoteException failure) {
107	                account.pendingRelease.addAll(attempted);
108	                try { releasePending(account); }
109	                catch (RemoteException compensation) { failure.addSuppressed(compensation); }
110	                throw new RemoteException("Reservation failed; incomplete cleanup is retained for retry", failure);
111	            }
112	            if (!available) {
113	                account.pendingRelease.addAll(attempted);
114	                releasePending(account);
115	                return false;
116	            }
117	            account.bookings.addAll(trip);
118	            return true;
119	        }
