122	    private void releasePending(Account account) throws RemoteException {
123	        RemoteException failure = null;
124	        Iterator<Booking> pending = account.pendingRelease.iterator();
125	        while (pending.hasNext()) {
126	            Booking booking = pending.next();
127	            try {
128	                if (!booking.manager.releaseInventory(booking.id))
129	                    throw new RemoteException("Unable to cancel reservation " + booking.id);
130	                pending.remove();
131	            } catch (RemoteException error) {
132	                if (failure == null) failure = error;
133	                else failure.addSuppressed(error);
134	            }
135	        }
136	        if (failure != null)
137	            throw new RemoteException("Incomplete reservation cleanup; retry this customer operation after backend recovery", failure);
138	    }
