23	        acceptor = Services.daemonFactory("tcp-accept").newThread(this::accept); acceptor.start();
24	    }
25	    public static TcpServer inventory(int port, ResourceManager manager) throws IOException {
26	        ThreadPoolExecutor workers = new ThreadPoolExecutor(4, 4, 0, TimeUnit.MILLISECONDS,
27	                new ArrayBlockingQueue<>(256), Services.daemonFactory("tcp-inventory"));
28	        try {
29	            TcpServer server = new TcpServer(port, (method, args) -> {
30	                try { return CompletableFuture.supplyAsync(() -> Services.call(manager, method, args), workers); }
31	                catch (RejectedExecutionException busy) { return CompletableFuture.failedFuture(busy); }
32	            }, true);
33	            server.workers = workers; return server;
34	        } catch (IOException failure) { workers.shutdownNow(); throw failure; }
35	    }
36	    public int port() { return listener.getLocalPort(); }
37	    private void accept() {
38	        try {
39	            while (!listener.isClosed()) {
40	                Socket socket = listener.accept();
41	                if (!permits.tryAcquire()) { socket.close(); continue; }
42	                try {
43	                    synchronized (this) {
44	                        if (listener.isClosed()) { socket.close(); permits.release(); continue; }
45	                        socket.setTcpNoDelay(true); Session session = new Session(socket); sessions.add(session); session.start();
46	                    }
47	                }
48	                catch (Exception failure) { socket.close(); permits.release(); }
49	            }
50	        } catch (IOException error) { if (!listener.isClosed()) close(); }
51	    }
52	    private final class Session {
53	        final Socket socket;
54	        final BlockingQueue<Protocol.Response> outgoing = new ArrayBlockingQueue<>(1024);
55	        final AtomicInteger inflight = new AtomicInteger();
56	        final Thread reader;
57	        final Thread writer;
58	        boolean closed;
59	        Session(Socket socket) {
60	            this.socket = socket;
61	            reader = Services.daemonFactory("tcp-session-read").newThread(this::read);
62	            writer = Services.daemonFactory("tcp-session-write").newThread(this::write);
63	        }
64	        void start() { reader.start(); writer.start(); }
65	        void read() {
66	            try {
67	                while (true) {
68	                    Object frame = Protocol.read(socket.getInputStream());
69	                    if (!(frame instanceof Protocol.Request request)) throw new IOException("Expected request");
70	                    if (inflight.incrementAndGet() > 1024) throw new IOException("Too many pending requests");
71	                    CompletionStage<Object> reply;
72	                    try { reply = service.invoke(Operations.resolve(request.operation(), request.arguments(), inventory), request.arguments()); }
73	                    catch (Exception invalid) { reply = CompletableFuture.failedFuture(invalid); }
74	                    reply.whenComplete((value, error) -> {
75	                        inflight.decrementAndGet();
76	                        String message = error == null ? null : Services.cause(error).toString();
77	                        if (!outgoing.offer(new Protocol.Response(request.id(), value, message))) close();
78	                    });
79	                }
80	            } catch (Exception error) { close(); }
81	        }
82	        void write() {
83	            try { while (true) Protocol.write(socket.getOutputStream(), outgoing.take()); }
84	            catch (Exception error) { close(); }
85	        }
86	        synchronized void close() {
87	            if (closed) return;
88	            closed = true;
89	            try { socket.close(); } catch (IOException ignored) { }
90	            reader.interrupt(); writer.interrupt(); outgoing.clear(); sessions.remove(this); permits.release();
91	        }
92	    }
