405		public static Vector<String> parse(String command)
406		{
407			Vector<String> arguments = new Vector<String>();
408			StringTokenizer tokenizer = new StringTokenizer(command,",");
409			String argument = "";
410			while (tokenizer.hasMoreTokens())
411			{
412				argument = tokenizer.nextToken();
413				argument = argument.trim();
414				arguments.add(argument);
415			}
416			return arguments;
417		}
418	
419		public static void checkArgumentsCount(Integer expected, Integer actual) throws IllegalArgumentException
420		{
421			if (expected != actual)
422			{
423				throw new IllegalArgumentException("Invalid number of arguments. Expected " + (expected - 1) + ", received " + (actual - 1) + ". Location \"help,<CommandName>\" to check usage of this command");
424			}
425		}
