433		{
434			// Stage 1: support both the handout's 0/1 and the console help's Y/N flags.
435			if (string.equalsIgnoreCase("true") || string.equalsIgnoreCase("y") || string.equals("1")) return true;
436			if (string.equalsIgnoreCase("false") || string.equalsIgnoreCase("n") || string.equals("0")) return false;
437			throw new IllegalArgumentException("Expected a bundle flag: 0/1, Y/N, or true/false");
