package Server.TCP;

import Server.Common.AsyncMiddleware;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;

/** Stage 7: TCP on both links, with the shared asynchronous customer service. */
public final class TCPMiddleware {
    private static TcpChannel connect(String endpoint, long timeout) throws Exception {
        int separator = endpoint.lastIndexOf(':');
        if (separator <= 0) throw new IllegalArgumentException("Expected backend host:port: " + endpoint);
        return new TcpChannel(endpoint.substring(0, separator), Integer.parseInt(endpoint.substring(separator + 1)), timeout);
    }
    public static void main(String[] args) {
        if (args.length < 4 || args.length > 5) {
            System.err.println("Usage: TCPMiddleware port flightsHost:port carsHost:port roomsHost:port [timeoutMillis]");
            System.exit(1);
        }
        List<TcpChannel> channels = new ArrayList<>();
        try {
            long timeout = args.length == 5 ? Long.parseLong(args[4]) : 30000;
            for (int i = 1; i <= 3; i++) channels.add(connect(args[i], timeout));
            AsyncMiddleware service = new AsyncMiddleware("Middleware", channels.get(0), channels.get(1), channels.get(2));
            try (TcpServer server = new TcpServer(Integer.parseInt(args[0]), service, false)) {
                Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                    server.close(); channels.forEach(TcpChannel::close);
                }));
                System.out.println("Middleware ready on TCP " + server.port());
                new CountDownLatch(1).await();
            }
        } catch (Exception failure) {
            System.err.println("TCP middleware startup failed: " + failure);
            channels.forEach(TcpChannel::close); System.exit(1);
        } finally { channels.forEach(TcpChannel::close); }
    }
}

package Client;

import Server.Common.Services;
import Server.Interface.IResourceManager;
import Server.TCP.TcpChannel;
import java.io.IOException;

/** Stage 7: the console blocks through the general service proxy, one command at a time. */
public final class TCPClient extends Client implements AutoCloseable {
    private final String host;
    private final int port;
    private final long timeout;
    private TcpChannel channel;

    public TCPClient(String host, int port, long timeout) {
        this.host = host; this.port = port; this.timeout = timeout;
    }
    public void connectServer() {
        close();
        try {
            channel = new TcpChannel(host, port, timeout);
            // Every interface method shares invocation, framing, correlation, and error handling.
            m_resourceManager = Services.blocking(IResourceManager.class, channel);
            System.out.println("Connected to TCP middleware " + host + ":" + port);
        } catch (IOException failure) { throw new IllegalStateException("TCP connection failed", failure); }
    }
    public void close() { if (channel != null) channel.close(); }
    public static void main(String[] args) {
        if (args.length > 3) {
            System.err.println("Usage: TCPClient [host [port [timeoutMillis]]]"); System.exit(1);
        }
        try (TCPClient client = new TCPClient(args.length > 0 ? args[0] : "localhost",
                args.length > 1 ? Integer.parseInt(args[1]) : 4004,
                args.length > 2 ? Long.parseLong(args[2]) : 30000)) {
            Runtime.getRuntime().addShutdownHook(new Thread(client::close));
            client.connectServer(); client.start();
        } catch (Exception failure) {
            System.err.println("TCP client failed: " + failure); System.exit(1);
        }
    }
}

package Server.TCP;

import Server.Common.ResourceManager;
import java.util.concurrent.CountDownLatch;

/** Stage 7: standalone inventory role; only the process main thread waits for shutdown. */
public final class TCPResourceManager {
    public static void main(String[] args) {
        if (args.length != 2) {
            System.err.println("Usage: TCPResourceManager name port"); System.exit(1);
        }
        try (TcpServer server = TcpServer.inventory(Integer.parseInt(args[1]), new ResourceManager(args[0]))) {
            Runtime.getRuntime().addShutdownHook(new Thread(server::close));
            System.out.println(args[0] + " ready on TCP " + server.port());
            new CountDownLatch(1).await();
        } catch (Exception failure) {
            System.err.println("TCP inventory startup failed: " + failure); System.exit(1);
        }
    }
}

