8	public final class Services {
9	    private static final ExecutorService RMI = Executors.newFixedThreadPool(16, daemonFactory("rmi-adapter"));
10	    private Services() { }
11	    public static ThreadFactory daemonFactory(String name) {
12	        return task -> { Thread thread = new Thread(task, name); thread.setDaemon(true); return thread; };
13	    }
14	    public static Object call(Object service, Method method, Object[] arguments) {
15	        try { return method.invoke(service, arguments); }
16	        catch (InvocationTargetException error) { throw new CompletionException(error.getCause()); }
17	        catch (Exception error) { throw new CompletionException(error); }
18	    }
19	    public static AsyncService remote(Object service) {
20	        return (method, arguments) -> CompletableFuture.supplyAsync(() -> call(service, method, arguments), RMI);
21	    }
22	    public static Throwable cause(Throwable error) {
23	        while ((error instanceof CompletionException || error instanceof ExecutionException) && error.getCause() != null)
24	            error = error.getCause();
25	        return error;
26	    }
27	    public static <T> T blocking(Class<T> type, AsyncService service) {
28	        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (proxy, method, args) -> {
29	            if (method.getDeclaringClass() == Object.class) {
30	                switch (method.getName()) {
31	                    case "toString": return "Service proxy: " + type.getSimpleName();
32	                    case "hashCode": return System.identityHashCode(proxy);
33	                    case "equals": return proxy == args[0];
34	                    default: throw new IllegalArgumentException();
35	                }
36	            }
37	            try { return service.invoke(method, args == null ? new Object[0] : args).toCompletableFuture().get(); }
38	            catch (InterruptedException error) { Thread.currentThread().interrupt(); throw new RemoteException("Interrupted", error); }
39	            catch (ExecutionException error) { throw new RemoteException("Service request failed", cause(error)); }
