1	package Server.TCP;
2	
3	import Server.Common.AsyncService;
4	import Server.Common.Services;
5	import java.io.*;
6	import java.lang.reflect.Method;
7	import java.net.*;
8	import java.rmi.RemoteException;
9	import java.util.concurrent.*;
10	import java.util.concurrent.atomic.AtomicLong;
11	
12	/** Stage 6: multiplexed async connection. invoke queues a frame and returns immediately. */
13	public final class TcpChannel implements AsyncService, AutoCloseable {
14	    private static final ScheduledExecutorService TIMER = Executors.newSingleThreadScheduledExecutor(Services.daemonFactory("tcp-timeouts"));
15	    private final Socket socket = new Socket();
16	    private final long timeout;
17	    private final AtomicLong ids = new AtomicLong();
18	    private final ConcurrentMap<Long, CompletableFuture<Object>> pending = new ConcurrentHashMap<>();
19	    private final BlockingQueue<Protocol.Request> outgoing = new ArrayBlockingQueue<>(1024);
20	    private final Thread reader;
21	    private final Thread writer;
22	    private boolean closed;
23	
24	    public TcpChannel(String host, int port, long timeoutMillis) throws IOException {
25	        if (timeoutMillis < 1 || timeoutMillis > Integer.MAX_VALUE) throw new IllegalArgumentException("Invalid timeout");
26	        timeout = timeoutMillis;
27	        try { socket.connect(new InetSocketAddress(host, port), (int)timeoutMillis); socket.setTcpNoDelay(true); }
28	        catch (IOException error) { socket.close(); throw error; }
29	        reader = Services.daemonFactory("tcp-replies").newThread(this::read);
30	        writer = Services.daemonFactory("tcp-requests").newThread(this::write);
31	        reader.start(); writer.start();
32	    }
33	
34	    public synchronized CompletionStage<Object> invoke(Method method, Object[] arguments) {
35	        if (closed) return CompletableFuture.failedFuture(new RemoteException("TCP channel closed"));
36	        if (pending.size() >= 1024) return CompletableFuture.failedFuture(new RemoteException("TCP channel overloaded"));
37	        long id = ids.incrementAndGet(); CompletableFuture<Object> future = new CompletableFuture<>();
38	        pending.put(id, future);
39	        if (!outgoing.offer(new Protocol.Request(id, Operations.key(method), arguments.clone()))) {
40	            pending.remove(id); future.completeExceptionally(new RemoteException("TCP writer overloaded")); return future;
41	        }
42	        ScheduledFuture<?> deadline = TIMER.schedule(() -> fail(new SocketTimeoutException("TCP reply timed out; mutation outcome may be uncertain")), timeout, TimeUnit.MILLISECONDS);
43	        future.whenComplete((value, error) -> deadline.cancel(false));
44	        return future;
45	    }
46	    private void read() {
47	        try {
48	            while (true) {
49	                Object frame = Protocol.read(socket.getInputStream());
50	                if (!(frame instanceof Protocol.Response response)) throw new IOException("Expected response");
51	                CompletableFuture<Object> future = pending.remove(response.id());
52	                if (future == null) throw new IOException("Unexpected response ID");
53	                if (response.error() == null) future.complete(response.value());
54	                else future.completeExceptionally(new RemoteException(response.error()));
55	            }
56	        } catch (Exception error) { fail(error); }
57	    }
58	    private void write() {
59	        try { while (true) Protocol.write(socket.getOutputStream(), outgoing.take()); }
60	        catch (Exception error) { fail(error); }
61	    }
62	    private synchronized void fail(Throwable error) {
63	        if (closed) return;
64	        closed = true;
65	        try { socket.close(); } catch (IOException ignored) { }
66	        reader.interrupt(); writer.interrupt(); outgoing.clear();
67	        pending.forEach((id, future) -> future.completeExceptionally(new RemoteException("TCP connection failed", error)));
68	        pending.clear();
69	    }
70	    public void close() { fail(new IOException("TCP channel closed")); }
71	}
